[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Leap Studio — Your Reinvention and Experience Partner</title>
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800;900&display=swap" rel="stylesheet">
  <style>
    /* ── Design Tokens ── */
    :root {
      --bg: #0A0A0A;
      --bg-surface: #111111;
      --bg-card: #161616;
      --bg-card-hover: #1C1C1C;
      --border: #1E1E1E;
      --border-hover: #2E2E2E;
      --text: #FFFFFF;
      --text-secondary: #A3A3A3;
      --text-muted: #5A5A5A;
      --accent: #6C8FFF;
      --accent-hover: #8BABFF;
      --accent-warm: #E2A03F;
      --accent-warm-hover: #F0B95C;
      --radius: 0.75rem;
      --radius-lg: 1rem;
      --font: 'Inter', system-ui, -apple-system, sans-serif;
      --transition: 200ms ease;
    }

    /* ── Reset & Base ── */
    *, *::before, *::after { margin: 0; padding: 0; box-sizing: border-box; }
    html { scroll-behavior: smooth; -webkit-font-smoothing: antialiased; }
    body {
      font-family: var(--font);
      background: var(--bg);
      color: var(--text);
      line-height: 1.6;
      overflow-x: hidden;
    }
    a { color: inherit; text-decoration: none; }
    button { font-family: inherit; cursor: pointer; border: none; background: none; color: inherit; }
    ul { list-style: none; }
    img { display: block; max-width: 100%; }

    /* ── Utility ── */
    .container { max-width: 1280px; margin: 0 auto; padding: 0 1.5rem; }
    .section-pad { padding: 6rem 0; }
    @media (min-width: 768px) { .section-pad { padding: 8rem 0; } }

    /* ── Buttons ── */
    .btn {
      display: inline-flex; align-items: center; gap: 0.5rem;
      padding: 0.8rem 1.75rem; border-radius: var(--radius);
      font-weight: 600; font-size: 0.9rem; letter-spacing: 0.01em;
      transition: all var(--transition);
    }
    .btn-primary { background: var(--text); color: var(--bg); }
    .btn-primary:hover { background: var(--accent-hover); color: var(--text); transform: translateY(-1px); }
    .btn-outline { border: 1px solid var(--border-hover); color: var(--text); }
    .btn-outline:hover { border-color: var(--text); background: rgba(255,255,255,0.04); }
    .btn-accent { background: var(--accent); color: var(--bg); }
    .btn-accent:hover { background: var(--accent-hover); transform: translateY(-1px); }
    .btn-warm { background: var(--accent-warm); color: var(--bg); }
    .btn-warm:hover { background: var(--accent-warm-hover); transform: translateY(-1px); }
    .btn-ghost { color: var(--accent); padding: 0.5rem 0; }
    .btn-ghost:hover { color: var(--accent-hover); }
    .btn-ghost svg { transition: transform var(--transition); }
    .btn-ghost:hover svg { transform: translateX(3px); }

    /* ── Navigation ── */
    .nav {
      position: fixed; top: 0; left: 0; right: 0; z-index: 100;
      background: rgba(10,10,10,0.85); backdrop-filter: blur(20px);
      border-bottom: 1px solid var(--border);
      transition: background var(--transition);
    }
    .nav-inner {
      display: flex; align-items: center; justify-content: space-between;
      height: 4rem; max-width: 1280px; margin: 0 auto; padding: 0 1.5rem;
    }
    .nav-logo { font-weight: 800; font-size: 1.25rem; letter-spacing: -0.03em; }
    .nav-logo span { color: var(--accent); }
    .nav-links { display: none; gap: 2rem; align-items: center; }
    .nav-links a {
      font-size: 0.85rem; font-weight: 500; color: var(--text-secondary);
      transition: color var(--transition); letter-spacing: 0.01em;
    }
    .nav-links a:hover { color: var(--text); }
    .nav-right { display: flex; align-items: center; gap: 1rem; }

    /* Language selector */
    .lang-selector { position: relative; }
    .lang-toggle {
      display: flex; align-items: center; gap: 0.35rem;
      font-size: 0.8rem; color: var(--text-secondary);
      padding: 0.4rem 0.6rem; border-radius: 0.375rem;
      transition: all var(--transition);
    }
    .lang-toggle:hover { color: var(--text); background: rgba(255,255,255,0.05); }
    .lang-toggle svg { width: 14px; height: 14px; }
    .lang-dropdown {
      position: absolute; top: calc(100% + 0.5rem); right: 0;
      background: var(--bg-card); border: 1px solid var(--border);
      border-radius: var(--radius); min-width: 160px;
      opacity: 0; visibility: hidden; transform: translateY(-8px);
      transition: all 200ms ease; overflow: hidden;
    }
    .lang-dropdown.active { opacity: 1; visibility: visible; transform: translateY(0); }
    .lang-dropdown a {
      display: block; padding: 0.65rem 1rem; font-size: 0.85rem;
      color: var(--text-secondary); transition: all var(--transition);
    }
    .lang-dropdown a:hover { background: rgba(255,255,255,0.05); color: var(--text); }
    .lang-dropdown a.active-lang { color: var(--accent); }

    /* Mobile menu */
    .hamburger { display: flex; flex-direction: column; gap: 5px; padding: 4px; }
    .hamburger span {
      display: block; width: 22px; height: 1.5px; background: var(--text);
      transition: all 300ms ease; border-radius: 1px;
    }
    .hamburger.active span:nth-child(1) { transform: rotate(45deg) translate(4.5px, 4.5px); }
    .hamburger.active span:nth-child(2) { opacity: 0; }
    .hamburger.active span:nth-child(3) { transform: rotate(-45deg) translate(4.5px, -4.5px); }

    .mobile-menu {
      position: fixed; top: 4rem; left: 0; right: 0; bottom: 0;
      background: rgba(10,10,10,0.98); backdrop-filter: blur(20px);
      z-index: 99; padding: 2rem 1.5rem;
      transform: translateX(100%); transition: transform 350ms ease;
    }
    .mobile-menu.active { transform: translateX(0); }
    .mobile-menu a {
      display: block; padding: 1rem 0; font-size: 1.25rem; font-weight: 500;
      border-bottom: 1px solid var(--border); color: var(--text-secondary);
      transition: color var(--transition);
    }
    .mobile-menu a:hover { color: var(--text); }

    @media (min-width: 1024px) {
      .nav-links { display: flex; }
      .hamburger { display: none; }
    }

    /* ── Hero Carousel ── */
    .hero {
      position: relative; min-height: 100vh; display: flex; align-items: center;
      overflow: hidden; padding-top: 4rem;
    }
    .hero-slide {
      position: absolute; inset: 0; display: flex; align-items: center;
      opacity: 0; transition: opacity 800ms ease; pointer-events: none;
    }
    .hero-slide.active { opacity: 1; pointer-events: auto; }
    .hero-slide-bg {
      position: absolute; inset: 0; z-index: 0;
    }
    .hero-slide-bg::after {
      content: ''; position: absolute; inset: 0;
      background: linear-gradient(135deg, rgba(10,10,10,0.92) 0%, rgba(10,10,10,0.7) 50%, rgba(10,10,10,0.4) 100%);
    }
    .hero-content {
      position: relative; z-index: 1; max-width: 1280px; margin: 0 auto;
      padding: 0 1.5rem; width: 100%;
    }
    .hero-tag {
      display: inline-block; font-size: 0.7rem; font-weight: 600;
      letter-spacing: 0.15em; text-transform: uppercase; color: var(--accent);
      margin-bottom: 1.25rem; padding: 0.35rem 0.8rem;
      border: 1px solid rgba(108,143,255,0.3); border-radius: 2rem;
      background: rgba(108,143,255,0.08);
    }
    .hero-title {
      font-size: clamp(2.25rem, 5vw, 4rem); font-weight: 800;
      line-height: 1.08; letter-spacing: -0.03em; max-width: 700px;
      margin-bottom: 1.25rem;
    }
    .hero-desc {
      font-size: 1.05rem; color: var(--text-secondary); max-width: 520px;
      line-height: 1.65; margin-bottom: 2rem;
    }
    .hero-controls {
      position: absolute; bottom: 3rem; left: 50%; transform: translateX(-50%);
      z-index: 10; display: flex; align-items: center; gap: 0.75rem;
    }
    .hero-dot {
      width: 8px; height: 8px; border-radius: 50%;
      background: rgba(255,255,255,0.25); cursor: pointer;
      transition: all var(--transition);
    }
    .hero-dot.active { background: var(--accent); width: 28px; border-radius: 4px; }
    .hero-arrows {
      position: absolute; bottom: 3rem; right: 1.5rem; z-index: 10;
      display: flex; gap: 0.5rem;
    }
    @media (min-width: 1024px) { .hero-arrows { right: calc((100vw - 1280px)/2 + 1.5rem); } }
    .hero-arrow {
      width: 44px; height: 44px; border-radius: 50%;
      border: 1px solid rgba(255,255,255,0.15); display: flex;
      align-items: center; justify-content: center;
      transition: all var(--transition); color: var(--text-secondary);
    }
    .hero-arrow:hover { border-color: var(--text); color: var(--text); background: rgba(255,255,255,0.05); }
    .hero-arrow svg { width: 18px; height: 18px; }

    /* Hero slide backgrounds */
    .hero-slide-1 .hero-slide-bg { background: linear-gradient(135deg, #0A0A0A 0%, #0D1B3E 40%, #1A1040 100%); }
    .hero-slide-2 .hero-slide-bg { background: linear-gradient(135deg, #0A0A0A 0%, #1A2A1A 40%, #0D1B0D 100%); }
    .hero-slide-3 .hero-slide-bg { background: linear-gradient(135deg, #0A0A0A 0%, #2A1A1A 40%, #1A0D0D 100%); }
    .hero-slide-4 .hero-slide-bg { background: linear-gradient(135deg, #0A0A0A 0%, #1A1A2E 40%, #2E1A2E 100%); }
    .hero-slide-5 .hero-slide-bg { background: linear-gradient(135deg, #0A0A0A 0%, #1A2E2E 40%, #0D2E1A 100%); }

    /* ── Section Headers ── */
    .section-header { margin-bottom: 3rem; }
    .section-label {
      font-size: 0.7rem; font-weight: 600; letter-spacing: 0.15em;
      text-transform: uppercase; color: var(--accent); margin-bottom: 0.75rem;
    }
    .section-title {
      font-size: clamp(1.75rem, 3.5vw, 2.75rem); font-weight: 800;
      line-height: 1.1; letter-spacing: -0.02em; max-width: 600px;
    }
    .section-subtitle {
      font-size: 1.05rem; color: var(--text-secondary);
      margin-top: 1rem; max-width: 540px; line-height: 1.65;
    }

    /* ── Team Section ── */
    .team-section { background: var(--bg-surface); }
    .region-tabs {
      display: flex; gap: 0.25rem; margin-bottom: 2.5rem;
      border-bottom: 1px solid var(--border); padding-bottom: 0;
    }
    .region-tab {
      padding: 0.75rem 1.25rem; font-size: 0.85rem; font-weight: 500;
      color: var(--text-muted); position: relative;
      transition: color var(--transition);
    }
    .region-tab::after {
      content: ''; position: absolute; bottom: -1px; left: 0; right: 0;
      height: 2px; background: var(--accent); transform: scaleX(0);
      transition: transform 300ms ease;
    }
    .region-tab:hover { color: var(--text-secondary); }
    .region-tab.active { color: var(--text); }
    .region-tab.active::after { transform: scaleX(1); }

    .team-carousel-wrapper { position: relative; }
    .team-carousel {
      display: flex; gap: 1.25rem; overflow-x: auto;
      scroll-snap-type: x mandatory; -webkit-overflow-scrolling: touch;
      scrollbar-width: none; padding-bottom: 1rem;
    }
    .team-carousel::-webkit-scrollbar { display: none; }

    .team-card {
      flex: 0 0 320px; scroll-snap-align: start;
      background: var(--bg-card); border: 1px solid var(--border);
      border-radius: var(--radius-lg); overflow: hidden;
      transition: all var(--transition);
    }
    .team-card:hover { border-color: var(--border-hover); transform: translateY(-2px); }
    .team-card-img {
      width: 100%; height: 280px; background: var(--bg-surface);
      object-fit: cover;
    }
    .team-card-body { padding: 1.5rem; }
    .team-card-quote {
      font-size: 0.9rem; line-height: 1.6; color: var(--text-secondary);
      font-style: italic; margin-bottom: 1.25rem;
      display: -webkit-box; -webkit-line-clamp: 4; -webkit-box-orient: vertical;
      overflow: hidden;
    }
    .team-card-name { font-weight: 700; font-size: 1rem; margin-bottom: 0.15rem; }
    .team-card-title { font-size: 0.8rem; color: var(--text-muted); margin-bottom: 1rem; }
    .team-card-cta {
      font-size: 0.8rem; font-weight: 600; color: var(--accent);
      display: inline-flex; align-items: center; gap: 0.4rem;
      transition: color var(--transition);
    }
    .team-card-cta:hover { color: var(--accent-hover); }
    .team-card-cta svg { width: 14px; height: 14px; transition: transform var(--transition); }
    .team-card-cta:hover svg { transform: translateX(3px); }

    .team-nav-arrows {
      display: flex; gap: 0.5rem; margin-top: 1.5rem;
    }
    .team-nav-arrow {
      width: 40px; height: 40px; border-radius: 50%;
      border: 1px solid var(--border); display: flex;
      align-items: center; justify-content: center;
      transition: all var(--transition); color: var(--text-secondary);
    }
    .team-nav-arrow:hover { border-color: var(--text); color: var(--text); }
    .team-nav-arrow svg { width: 16px; height: 16px; }

    .team-region-content { display: none; }
    .team-region-content.active { display: block; animation: fadeIn 400ms ease; }

    @media (min-width: 768px) {
      .team-card { flex: 0 0 360px; }
    }

    /* ── Work Showcase ── */
    .work-section { overflow: hidden; }
    .work-carousel {
      display: flex; gap: 1.25rem; overflow-x: auto;
      scroll-snap-type: x mandatory; -webkit-overflow-scrolling: touch;
      scrollbar-width: none; padding-bottom: 1rem;
      cursor: grab;
    }
    .work-carousel::-webkit-scrollbar { display: none; }
    .work-carousel:active { cursor: grabbing; }

    .work-card {
      flex: 0 0 340px; scroll-snap-align: start;
      border-radius: var(--radius-lg); overflow: hidden;
      border: 1px solid var(--border); background: var(--bg-card);
      transition: all var(--transition);
    }
    .work-card:hover { border-color: var(--border-hover); transform: translateY(-3px); }
    .work-card-img {
      width: 100%; height: 220px; background: var(--bg-surface);
      object-fit: cover; position: relative; overflow: hidden;
    }
    .work-card-img-overlay {
      position: absolute; bottom: 0; left: 0; right: 0;
      padding: 1rem; background: linear-gradient(transparent, rgba(0,0,0,0.8));
    }
    .work-card-client {
      font-size: 0.7rem; font-weight: 600; letter-spacing: 0.1em;
      text-transform: uppercase; color: var(--accent-warm);
    }
    .work-card-body { padding: 1.25rem; }
    .work-card-title { font-weight: 700; font-size: 1rem; line-height: 1.35; margin-bottom: 0.75rem; }
    .work-card-quote {
      font-size: 0.82rem; color: var(--text-secondary); line-height: 1.55;
      font-style: italic; display: -webkit-box; -webkit-line-clamp: 3;
      -webkit-box-orient: vertical; overflow: hidden;
    }
    .work-card-quote-attr { font-style: normal; color: var(--text-muted); font-size: 0.78rem; margin-top: 0.35rem; }

    .work-nav-arrows { display: flex; gap: 0.5rem; margin-top: 1.5rem; }

    @media (min-width: 768px) {
      .work-card { flex: 0 0 400px; }
    }

    /* ── CTA Banner ── */
    .cta-banner {
      background: linear-gradient(135deg, #0F1A3C 0%, #1A0F3C 50%, #0F1A2E 100%);
      border-top: 1px solid var(--border); border-bottom: 1px solid var(--border);
      text-align: center; padding: 5rem 1.5rem;
    }
    .cta-banner-title {
      font-size: clamp(1.75rem, 3.5vw, 2.75rem); font-weight: 800;
      letter-spacing: -0.02em; margin-bottom: 1rem;
    }
    .cta-banner-text {
      font-size: 1.05rem; color: var(--text-secondary); max-width: 560px;
      margin: 0 auto 2rem; line-height: 1.65;
    }

    /* ── How We Work ── */
    .how-section { border-top: 1px solid var(--border); }
    .how-grid {
      display: grid; gap: 3rem; align-items: center;
    }
    @media (min-width: 768px) {
      .how-grid { grid-template-columns: 1fr 1fr; }
    }
    .how-title {
      font-size: clamp(1.75rem, 3.5vw, 2.75rem); font-weight: 800;
      letter-spacing: -0.02em; line-height: 1.1;
    }
    .how-title span {
      background: linear-gradient(135deg, var(--accent), var(--accent-warm));
      -webkit-background-clip: text; -webkit-text-fill-color: transparent;
      background-clip: text;
    }
    .how-body { font-size: 1.05rem; color: var(--text-secondary); line-height: 1.7; margin-bottom: 1.5rem; }
    .how-visual {
      aspect-ratio: 4/3; background: var(--bg-surface);
      border: 1px solid var(--border); border-radius: var(--radius-lg);
      display: flex; align-items: center; justify-content: center;
      position: relative; overflow: hidden;
    }
    .how-visual::before {
      content: ''; position: absolute; inset: 0;
      background: radial-gradient(ellipse at center, rgba(108,143,255,0.08) 0%, transparent 70%);
    }
    .how-visual-label {
      font-size: 0.75rem; font-weight: 600; letter-spacing: 0.1em;
      text-transform: uppercase; color: var(--text-muted);
    }

    /* ── Insights ── */
    .insights-section { background: var(--bg-surface); }
    .insights-grid {
      display: grid; gap: 1.25rem;
    }
    @media (min-width: 640px) { .insights-grid { grid-template-columns: repeat(2, 1fr); } }
    @media (min-width: 1024px) { .insights-grid { grid-template-columns: repeat(3, 1fr); } }

    .insight-card {
      background: var(--bg-card); border: 1px solid var(--border);
      border-radius: var(--radius-lg); overflow: hidden;
      transition: all var(--transition);
    }
    .insight-card:hover { border-color: var(--border-hover); transform: translateY(-2px); }
    .insight-card-img {
      width: 100%; height: 160px; background: var(--bg-surface);
      object-fit: cover;
    }
    .insight-card-body { padding: 1.25rem; }
    .insight-type {
      font-size: 0.65rem; font-weight: 700; letter-spacing: 0.12em;
      text-transform: uppercase; color: var(--accent); margin-bottom: 0.5rem;
    }
    .insight-type.podcast { color: #E06CFF; }
    .insight-type.report { color: var(--accent-warm); }
    .insight-card-title { font-weight: 700; font-size: 0.95rem; line-height: 1.4; margin-bottom: 1rem; }
    .insight-card-cta {
      font-size: 0.8rem; font-weight: 600; color: var(--accent);
      display: inline-flex; align-items: center; gap: 0.4rem;
      transition: color var(--transition);
    }
    .insight-card-cta:hover { color: var(--accent-hover); }
    .insight-card-cta svg { width: 14px; height: 14px; transition: transform var(--transition); }
    .insight-card-cta:hover svg { transform: translateX(3px); }

    /* ── Principles ── */
    .principles-grid {
      display: grid; gap: 1.25rem;
    }
    @media (min-width: 640px) { .principles-grid { grid-template-columns: repeat(2, 1fr); } }
    @media (min-width: 1024px) { .principles-grid { grid-template-columns: repeat(4, 1fr); } }

    .principle-card {
      background: var(--bg-card); border: 1px solid var(--border);
      border-radius: var(--radius-lg); padding: 2rem 1.5rem;
      transition: all var(--transition); position: relative;
    }
    .principle-card:hover { border-color: var(--border-hover); transform: translateY(-2px); }
    .principle-num {
      font-size: 3rem; font-weight: 900; color: var(--bg);
      text-shadow: 1px 1px 0 var(--border); line-height: 1; margin-bottom: 1rem;
    }
    .principle-title {
      font-size: 1rem; font-weight: 700; margin-bottom: 0.75rem; line-height: 1.3;
    }
    .principle-desc { font-size: 0.85rem; color: var(--text-secondary); line-height: 1.6; }

    /* ── Footer ── */
    .footer {
      background: var(--bg-surface); border-top: 1px solid var(--border);
      padding: 4rem 0 2rem;
    }
    .footer-ctas {
      display: grid; gap: 1.5rem; margin-bottom: 3rem;
    }
    @media (min-width: 768px) { .footer-ctas { grid-template-columns: 1fr 1fr; } }
    .footer-cta-box {
      background: var(--bg-card); border: 1px solid var(--border);
      border-radius: var(--radius-lg); padding: 2rem;
      transition: border-color var(--transition);
    }
    .footer-cta-box:hover { border-color: var(--border-hover); }
    .footer-cta-text { font-size: 0.95rem; color: var(--text-secondary); margin-bottom: 1.25rem; line-height: 1.6; }
    .footer-links {
      display: flex; flex-wrap: wrap; gap: 1.5rem; margin-bottom: 2rem;
      padding-bottom: 2rem; border-bottom: 1px solid var(--border);
    }
    .footer-links a {
      font-size: 0.85rem; color: var(--text-secondary);
      transition: color var(--transition);
    }
    .footer-links a:hover { color: var(--text); }
    .footer-legal {
      display: flex; flex-wrap: wrap; gap: 1rem;
      font-size: 0.75rem; color: var(--text-muted);
    }
    .footer-legal a { color: var(--text-muted); transition: color var(--transition); }
    .footer-legal a:hover { color: var(--text-secondary); }
    .footer-divider { color: var(--text-muted); }

    /* ── Cookie Banner ── */
    .cookie-banner {
      position: fixed; bottom: 0; left: 0; right: 0; z-index: 200;
      background: var(--bg-card); border-top: 1px solid var(--border);
      padding: 1.25rem 1.5rem; transform: translateY(100%);
      transition: transform 400ms ease;
    }
    .cookie-banner.visible { transform: translateY(0); }
    .cookie-inner {
      max-width: 1280px; margin: 0 auto;
      display: flex; flex-wrap: wrap; align-items: center; gap: 1rem;
    }
    .cookie-text { font-size: 0.82rem; color: var(--text-secondary); flex: 1; min-width: 200px; }
    .cookie-actions { display: flex; gap: 0.5rem; flex-wrap: wrap; }
    .cookie-btn {
      padding: 0.5rem 1rem; border-radius: 0.375rem; font-size: 0.8rem;
      font-weight: 600; transition: all var(--transition);
    }
    .cookie-btn-accept { background: var(--accent); color: var(--bg); }
    .cookie-btn-accept:hover { background: var(--accent-hover); }
    .cookie-btn-manage { border: 1px solid var(--border); color: var(--text-secondary); }
    .cookie-btn-manage:hover { border-color: var(--text); color: var(--text); }
    .cookie-btn-decline { color: var(--text-muted); }
    .cookie-btn-decline:hover { color: var(--text-secondary); }

    /* ── Animations ── */
    @keyframes fadeIn {
      from { opacity: 0; transform: translateY(10px); }
      to { opacity: 1; transform: translateY(0); }
    }
    .fade-in { animation: fadeIn 600ms ease forwards; }
    .fade-in-delay-1 { animation-delay: 100ms; opacity: 0; }
    .fade-in-delay-2 { animation-delay: 200ms; opacity: 0; }
    .fade-in-delay-3 { animation-delay: 300ms; opacity: 0; }

    /* ── Scroll reveal ── */
    .reveal {
      opacity: 0; transform: translateY(30px);
      transition: opacity 600ms ease, transform 600ms ease;
    }
    .reveal.visible { opacity: 1; transform: translateY(0); }

    /* ── Scrollbar ── */
    ::-webkit-scrollbar { width: 6px; }
    ::-webkit-scrollbar-track { background: var(--bg); }
    ::-webkit-scrollbar-thumb { background: var(--border); border-radius: 3px; }
    ::-webkit-scrollbar-thumb:hover { background: var(--text-muted); }
  </style>
</head>
