  <script>
    // ── Hero Carousel ──
    (function() {
      const slides = document.querySelectorAll('.hero-slide');
      const dots = document.querySelectorAll('.hero-dot');
      let current = 0;
      let autoTimer = null;
      const INTERVAL = 5000;

      function goTo(index) {
        slides[current].classList.remove('active');
        dots[current].classList.remove('active');
        current = (index + slides.length) % slides.length;
        slides[current].classList.add('active');
        dots[current].classList.add('active');
      }

      function startAuto() {
        stopAuto();
        autoTimer = setInterval(() => goTo(current + 1), INTERVAL);
      }

      function stopAuto() {
        if (autoTimer) clearInterval(autoTimer);
      }

      dots.forEach(dot => {
        dot.addEventListener('click', () => {
          goTo(parseInt(dot.dataset.dot));
          startAuto();
        });
      });

      document.getElementById('heroPrev').addEventListener('click', () => {
        goTo(current - 1);
        startAuto();
      });

      document.getElementById('heroNext').addEventListener('click', () => {
        goTo(current + 1);
        startAuto();
      });

      const heroEl = document.getElementById('hero');
      heroEl.addEventListener('mouseenter', stopAuto);
      heroEl.addEventListener('mouseleave', startAuto);

      // Touch/swipe support for hero
      let touchStartX = 0;
      heroEl.addEventListener('touchstart', (e) => {
        touchStartX = e.changedTouches[0].screenX;
        stopAuto();
      }, { passive: true });
      heroEl.addEventListener('touchend', (e) => {
        const diff = e.changedTouches[0].screenX - touchStartX;
        if (Math.abs(diff) > 50) {
          diff > 0 ? goTo(current - 1) : goTo(current + 1);
        }
        startAuto();
      }, { passive: true });

      startAuto();
    })();

    // ── Team Region Toggle ──
    (function() {
      const tabs = document.querySelectorAll('.region-tab');
      const contents = document.querySelectorAll('.team-region-content');

      tabs.forEach(tab => {
        tab.addEventListener('click', () => {
          const region = tab.dataset.region;
          tabs.forEach(t => t.classList.remove('active'));
          contents.forEach(c => c.classList.remove('active'));
          tab.classList.add('active');
          document.querySelector(`[data-region-content="${region}"]`).classList.add('active');
        });
      });
    })();

    // ── Carousel Scroll Navigation (Team + Work) ──
    (function() {
      // Team carousel arrows
      document.querySelectorAll('.team-nav-arrow[data-carousel]').forEach(btn => {
        btn.addEventListener('click', () => {
          const carousel = document.getElementById(btn.dataset.carousel);
          const dir = parseInt(btn.dataset.dir);
          const cardWidth = carousel.querySelector('.team-card')?.offsetWidth + 20 || 380;
          carousel.scrollBy({ left: dir * cardWidth, behavior: 'smooth' });
        });
      });

      // Work carousel arrows
      const workCarousel = document.getElementById('workCarousel');
      const workPrev = document.getElementById('workPrev');
      const workNext = document.getElementById('workNext');
      if (workPrev && workNext && workCarousel) {
        workPrev.addEventListener('click', () => {
          const cardWidth = workCarousel.querySelector('.work-card')?.offsetWidth + 20 || 420;
          workCarousel.scrollBy({ left: -cardWidth, behavior: 'smooth' });
        });
        workNext.addEventListener('click', () => {
          const cardWidth = workCarousel.querySelector('.work-card')?.offsetWidth + 20 || 420;
          workCarousel.scrollBy({ left: cardWidth, behavior: 'smooth' });
        });
      }

      // Drag-to-scroll for work carousel
      let isDown = false, startX, scrollLeft;
      if (workCarousel) {
        workCarousel.addEventListener('mousedown', (e) => {
          isDown = true;
          workCarousel.style.cursor = 'grabbing';
          startX = e.pageX - workCarousel.offsetLeft;
          scrollLeft = workCarousel.scrollLeft;
        });
        workCarousel.addEventListener('mouseleave', () => { isDown = false; workCarousel.style.cursor = 'grab'; });
        workCarousel.addEventListener('mouseup', () => { isDown = false; workCarousel.style.cursor = 'grab'; });
        workCarousel.addEventListener('mousemove', (e) => {
          if (!isDown) return;
          e.preventDefault();
          const x = e.pageX - workCarousel.offsetLeft;
          const walk = (x - startX) * 1.5;
          workCarousel.scrollLeft = scrollLeft - walk;
        });
      }
    })();

    // ── Language Selector ──
    (function() {
      const toggle = document.getElementById('langToggle');
      const dropdown = document.getElementById('langDropdown');

      toggle.addEventListener('click', (e) => {
        e.stopPropagation();
        dropdown.classList.toggle('active');
      });

      dropdown.querySelectorAll('a').forEach(link => {
        link.addEventListener('click', (e) => {
          e.preventDefault();
          dropdown.querySelectorAll('a').forEach(l => l.classList.remove('active-lang'));
          link.classList.add('active-lang');
          toggle.innerHTML = link.textContent + ' <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" style="width:12px;height:12px;"><polyline points="6 9 12 15 18 9"/></svg>';
          dropdown.classList.remove('active');
        });
      });

      document.addEventListener('click', () => {
        dropdown.classList.remove('active');
      });
    })();

    // ── Cookie Consent ──
    (function() {
      const banner = document.getElementById('cookieBanner');
      const acceptBtn = document.getElementById('cookieAccept');
      const manageBtn = document.getElementById('cookieManage');
      const declineBtn = document.getElementById('cookieDecline');
      const footerSettings = document.getElementById('footerCookieSettings');

      function showBanner() {
        if (!localStorage.getItem('cookieConsent')) {
          setTimeout(() => banner.classList.add('visible'), 800);
        }
      }

      function dismissBanner() {
        banner.classList.remove('visible');
      }

      acceptBtn.addEventListener('click', () => {
        localStorage.setItem('cookieConsent', 'accepted');
        dismissBanner();
      });

      declineBtn.addEventListener('click', () => {
        localStorage.setItem('cookieConsent', 'declined');
        dismissBanner();
      });

      manageBtn.addEventListener('click', () => {
        // Toggle a simple "managed" state — in production this would open a detailed preferences modal
        alert('Cookie preferences would be managed here. All cookies have been set to essential only.');
        localStorage.setItem('cookieConsent', 'managed');
        dismissBanner();
      });

      if (footerSettings) {
        footerSettings.addEventListener('click', (e) => {
          e.preventDefault();
          localStorage.removeItem('cookieConsent');
          banner.classList.add('visible');
        });
      }

      showBanner();
    })();

    // ── Mobile Menu ──
    (function() {
      const hamburger = document.getElementById('hamburger');
      const mobileMenu = document.getElementById('mobileMenu');

      hamburger.addEventListener('click', () => {
        hamburger.classList.toggle('active');
        mobileMenu.classList.toggle('active');
        document.body.style.overflow = mobileMenu.classList.contains('active') ? 'hidden' : '';
      });

      mobileMenu.querySelectorAll('a').forEach(link => {
        link.addEventListener('click', () => {
          hamburger.classList.remove('active');
          mobileMenu.classList.remove('active');
          document.body.style.overflow = '';
        });
      });
    })();

    // ── Scroll Reveal ──
    (function() {
      const reveals = document.querySelectorAll('.reveal');
      const observer = new IntersectionObserver((entries) => {
        entries.forEach(entry => {
          if (entry.isIntersecting) {
            entry.target.classList.add('visible');
            observer.unobserve(entry.target);
          }
        });
      }, { threshold: 0.1, rootMargin: '0px 0px -40px 0px' });

      reveals.forEach(el => observer.observe(el));
    })();

    // ── Smooth Scroll for Nav Links ──
    document.querySelectorAll('a[href^="#"]').forEach(anchor => {
      anchor.addEventListener('click', function(e) {
        const target = document.querySelector(this.getAttribute('href'));
        if (target) {
          e.preventDefault();
          target.scrollIntoView({ behavior: 'smooth', block: 'start' });
        }
      });
    });
  </script>
